-- Vacían las tablas por aquello que se corran dos veces (invetigado) --
USE master;
GO
IF EXISTS (SELECT name FROM sys.databases WHERE name = N'FraudeLink')
BEGIN
    ALTER DATABASE FraudeLink SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE FraudeLink;
END
GO

-- Crea la base de Datos --
CREATE DATABASE FraudeLink;
GO
-- Selecciono la Base --
USE FraudeLink;
GO

-- Tabla de clientes --
CREATE TABLE Cliente (
  cliente_id VARCHAR(10) PRIMARY KEY
);
GO
-- Tabla de cuentas --
CREATE TABLE Cuenta (
  cuenta_id VARCHAR(10) PRIMARY KEY
);
GO
-- Tabla de dispositivos --
CREATE TABLE Dispositivo (
  dispositivo_id VARCHAR(10) PRIMARY KEY
);
GO
-- Tabla de direcciones IP --
CREATE TABLE IP (
  ip_address VARCHAR(15) PRIMARY KEY
);
GO
-- Tabla de comercios --
CREATE TABLE Comercio (
  comercio_id VARCHAR(10) PRIMARY KEY
);
GO

CREATE TABLE Posee (
    cliente_id VARCHAR(10) NOT NULL,
    cuenta_id VARCHAR(10) NOT NULL,
    fecha DATE,
    CONSTRAINT FK_Posee_Cliente FOREIGN KEY (cliente_id) REFERENCES Cliente(cliente_id),
    CONSTRAINT FK_Posee_Cuenta FOREIGN KEY (cuenta_id) REFERENCES Cuenta(cuenta_id)
);
GO
-- USA_DISPOSITIVO --
CREATE TABLE Usa_Dispositivo (
    cuenta_id VARCHAR(10) NOT NULL,
    dispositivo_id VARCHAR(10) NOT NULL,
    fecha DATE,
    CONSTRAINT FK_UsaDisp_Cuenta FOREIGN KEY (cuenta_id) REFERENCES Cuenta(cuenta_id),
    CONSTRAINT FK_UsaDisp_Dispositivo FOREIGN KEY (dispositivo_id) REFERENCES Dispositivo(dispositivo_id)
);
GO
-- CONECTA_DESDE--
CREATE TABLE Conecta_Desde (
    cuenta_id VARCHAR(10) NOT NULL,
    ip_address VARCHAR(15) NOT NULL,
    fecha DATE,
    CONSTRAINT FK_Conecta_Cuenta FOREIGN KEY (cuenta_id) REFERENCES Cuenta(cuenta_id),
    CONSTRAINT FK_Conecta_IP FOREIGN KEY (ip_address) REFERENCES IP(ip_address)
);
GO
-- TRANSFIERE_A --
CREATE TABLE Transfiere_A (
    cuenta_origen VARCHAR(10) NOT NULL,
    cuenta_destino VARCHAR(10) NOT NULL,
    monto DECIMAL(14,2) NOT NULL
        CHECK (monto > 0),
    fecha DATE NOT NULL,
    CONSTRAINT FK_Transf_Origen FOREIGN KEY (cuenta_origen) REFERENCES Cuenta(cuenta_id),
    CONSTRAINT FK_Transf_Destino FOREIGN KEY (cuenta_destino) REFERENCES Cuenta(cuenta_id)
);
GO
-- PAGA_EN --
CREATE TABLE Paga_En (
    cuenta_id VARCHAR(10) NOT NULL,
    comercio_id VARCHAR(10) NOT NULL,
    monto DECIMAL(14,2) NOT NULL
        CHECK (monto > 0),
    fecha DATE NOT NULL,
    CONSTRAINT FK_Paga_Cuenta FOREIGN KEY (cuenta_id) REFERENCES Cuenta(cuenta_id),
    CONSTRAINT FK_Paga_Comercio FOREIGN KEY (comercio_id) REFERENCES Comercio(comercio_id)
);
GO

SET NOCOUNT ON;
GO

