-- Lo que se hace aquí, es qaue se verifican si los nodos se cargaron completamente--
SELECT (SELECT COUNT(*) FROM Cliente) + (SELECT COUNT(*) FROM Cuenta) + (SELECT COUNT(*) FROM Dispositivo) + (SELECT COUNT(*) FROM IP) + (SELECT COUNT(*) FROM Comercio) AS nodos;
GO
